import ghidra.app.script.GhidraScript;
import java.nio.file.*;
import java.util.*;
import com.google.gson.GsonBuilder;
/* Curated arithmetic and branch metadata, never a full function export. */
public class NumericAudit extends GhidraScript {
 byte[] pe; long le(int p){return (pe[p]&255L)|((pe[p+1]&255L)<<8)|((pe[p+2]&255L)<<16)|((pe[p+3]&255L)<<24);}
 byte[] raw(long va,int n){int h=(int)le(60),s=h+24+((pe[h+20]&255)|((pe[h+21]&255)<<8)),ns=(pe[h+6]&255)|((pe[h+7]&255)<<8);for(int k=0;k<ns;k++){int at=s+40*k;long x=va-0x400000-le(at+12);if(x>=0&&x+n<=le(at+16))return Arrays.copyOfRange(pe,(int)(le(at+20)+x),(int)(le(at+20)+x+n));}throw new IllegalArgumentException();}
 String sha(byte[]b)throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b));}
 public void run()throws Exception{
 String[]z=getScriptArgs();pe=Files.readAllBytes(Path.of(z[0]));if(!sha(pe).equals("bc073a930da5b03793c086f22eeeff6f2cc7d9c81ce650c6656d0d0c49af13f3"))throw new Exception("identity");long mod=currentProgram.getModificationNumber();List<Object> functions=new ArrayList<>(),constants=new ArrayList<>();
 for(long[]range:new long[][]{{0x4791e0,0x47953c},{0x4796a0,0x479739},{0x479860,0x47996e},{0x4ba090,0x4ba095},{0x4ba2b6,0x4ba2bb},{0x4ba320,0x4ba332},{0x4ba340,0x4ba345},{0x4ba171,0x4ba171},{0x402da4,0x402da9}}){List<Object> arithmetic=new ArrayList<>(),flow=new ArrayList<>();int count=0;long pc=range[0];while(pc<=range[1]){var i=currentProgram.getListing().getInstructionAt(toAddr(pc));if(i==null){disassemble(toAddr(pc));i=currentProgram.getListing().getInstructionAt(toAddr(pc));}if(i==null)throw new Exception("no instruction "+pc);byte[]b=i.getBytes();if(!Arrays.equals(b,raw(pc,b.length)))throw new Exception("bytes "+pc);String va=String.format("%08x",pc);String mnemonic=i.getMnemonicString();if(mnemonic.startsWith("F")||range[0]==0x4ba320){List<String> ops=new ArrayList<>();for(var p:i.getPcode())ops.add(p.toString());arithmetic.add(Map.of("va",va,"assembly",i.toString(),"pcode",ops));}
 if(i.getFlowType().isJump()||i.getFlowType().isCall()||i.getFlowType().isTerminal()){List<String> targets=new ArrayList<>();for(var t:i.getFlows())targets.add(t.toString());flow.add(Map.of("va",va,"assembly",i.toString(),"targets",targets,"fallthrough",String.valueOf(i.getFallThrough())));}
 pc+=i.getLength();count++;}functions.add(Map.of("entry",String.format("%08x",range[0]),"last_instruction",String.format("%08x",range[1]),"byte_length",pc-range[0],"retail_sha256",sha(raw(range[0],(int)(pc-range[0]))),"instructions_retail_checked",count,"arithmetic",arithmetic,"control_transfers",flow));}
 for(long va:new long[]{0x4be698,0x4be6e4,0x4be6e8,0x4be6d0,0x4be6e0,0x4be6ec,0x4be700,0x4be740,0x4be748}){int n=va>=0x4be700?8:4;byte[]b=new byte[n];currentProgram.getMemory().getBytes(toAddr(va),b);if(!Arrays.equals(b,raw(va,n)))throw new Exception("constant");constants.add(Map.of("va",String.format("%08x",va),"little_endian_hex",java.util.HexFormat.of().formatHex(b),"bytes",n));}
 List<Object> fpcontrols=new ArrayList<>();var it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){var i=it.next();if(Arrays.asList("FLDCW","FINIT","FNINIT").contains(i.getMnemonicString()))fpcontrols.add(Map.of("va",i.getAddress().toString(),"assembly",i.toString()));}
 var result=Map.of("functions",functions,"constants",constants,"listed_fp_control_instructions",fpcontrols,"modification_before",mod,"modification_after",currentProgram.getModificationNumber(),"scope","Private disposable read-only program; any disassembly exists only in this session. Curated arithmetic/CFG metadata, no full exports.");Files.writeString(Path.of(z[1]),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");println("Audited "+functions.size()+" bodies/thunks");}
}
